<?php
namespace App\Services;
use Illuminate\Support\Facades\{DB,Crypt,Http};
class AiProvider {
 public const TEXT_MODEL='gpt-4.1-mini';
 public const VOICE_MODEL='gpt-realtime-2.1';
 public const PRICES=['currency'=>'USD','checked_at'=>'2026-10-16','unit'=>'1 milhão de tokens','text_input'=>0.40,'text_output'=>1.60,'voice_audio_input'=>32,'voice_audio_output'=>64,'voice_text_input'=>4,'voice_text_output'=>24,'url'=>'https://developers.openai.com/api/docs/pricing'];
 public static function schema():array {return ['type'=>'object','properties'=>['reply'=>['type'=>'string'],'action'=>['type'=>'string','enum'=>['reply','handoff','stop']],'summary'=>['type'=>'string']],'required'=>['reply','action','summary'],'additionalProperties'=>false];}
 public static function answer(mixed $text):array {$answer=is_string($text)?json_decode($text,true):null;abort_unless(is_array($answer)&&is_string($answer['reply']??null)&&trim($answer['reply'])!==''&&mb_strlen($answer['reply'])<=3000&&in_array($answer['action']??null,['reply','handoff','stop'],true)&&is_string($answer['summary']??null)&&mb_strlen($answer['summary'])<=3000,502,'A IA retornou uma resposta inválida. Nenhuma mensagem foi enviada.');return array_intersect_key($answer,array_flip(['reply','action','summary']));}
 public function textProvider(int $w):string {return app(AiLocalProvider::class)->provider($w);}
 public function textReady(int $w):void {if($this->textProvider($w)==='qwen')app(AiLocalProvider::class)->ready($w);else $this->ready($w);}
 public function textLimit(int $w):int {return $this->textProvider($w)==='qwen'?(app(AiLocalProvider::class)->row($w)?->daily_requests??100):$this->connection($w)['daily_requests'];}
 public function connection(int $w):array {$r=DB::table('ai_connections')->where('workspace_id',$w)->first();$local=app(AiLocalProvider::class)->row($w);$provider=$local?->text_provider??'openai';return ['text_provider'=>$provider,'text_enabled'=>$provider==='qwen'?(bool)$local?->enabled:(bool)$r?->enabled,'voice_enabled'=>(bool)$r?->enabled,'configured'=>(bool)$r,'sip_configured'=>(bool)($r?->sip_secret&&$r?->project_id),'project_id'=>$r?->project_id,'enabled'=>(bool)$r?->enabled,'daily_requests'=>$r?->daily_requests??100,'prices'=>self::PRICES,'text_model'=>self::TEXT_MODEL,'voice_model'=>self::VOICE_MODEL];}
 public function save(int $w,array $d):array {return DB::transaction(function()use($w,$d){DB::table('voice_runtime')->where('id',1)->lockForUpdate()->firstOrFail();if(!empty($d['api_key'])||!empty($d['sip_secret'])||!empty($d['project_id']))abort_if(DB::table('ai_sessions')->where('workspace_id',$w)->whereIn('channel',['voice','phone'])->whereIn('status',['connecting','open','closing','transferring'])->exists(),409,'Encerre as sessões de voz antes de alterar as credenciais.');$old=DB::table('ai_connections')->where('workspace_id',$w)->first();abort_unless($old||!empty($d['api_key']),422,'Informe a chave de API para conectar.');$values=['enabled'=>$d['enabled'],'daily_requests'=>$d['daily_requests'],'updated_at'=>now()];if(!empty($d['api_key']))$values['credentials']=Crypt::encryptString($d['api_key']);if(!empty($d['sip_secret']))$values['sip_secret']=Crypt::encryptString($d['sip_secret']);if(!empty($d['project_id']))$values['project_id']=$d['project_id'];if(!$old)$values['created_at']=now();DB::table('ai_connections')->updateOrInsert(['workspace_id'=>$w],$values);return $this->connection($w);});}
 public function ready(int $w):void {abort_unless($this->connection($w)['enabled'],409,'Conecte a API de IA e autorize o consumo em Conexão e custos.');}
 public function request(int $w,bool $closing=false){if(!$closing)$this->ready($w);$c=DB::table('ai_connections')->where('workspace_id',$w)->first();abort_unless($c,409,'Conexão de IA não configurada.');$key=Crypt::decryptString($c->credentials);return Http::withToken($key)->acceptJson()->connectTimeout(5)->timeout(35)->withOptions(['allow_redirects'=>false]);}
 public function base():string {return app()->environment('testing')?config('ai_test.url','https://api.openai.com/v1'):'https://api.openai.com/v1';}
 public function text(int $w,string $prompt,array $history,?string $provider=null):array {
  $provider=$provider??$this->textProvider($w);if($provider==='qwen')return app(AiLocalProvider::class)->text($w,$prompt,$history);
  $schema=self::schema();
  try{$r=$this->request($w)->post($this->base().'/responses',['model'=>self::TEXT_MODEL,'store'=>false,'instructions'=>$prompt,'input'=>$history,'max_output_tokens'=>700,'text'=>['format'=>['type'=>'json_schema','name'=>'discai_reply','strict'=>true,'schema'=>$schema]]]);}catch(\Throwable $e){abort(502,'A IA não respondeu a tempo. Nenhuma mensagem foi enviada.');}
  abort_unless($r->successful(),502,'O provedor de IA recusou a solicitação. Confira a chave, o saldo e o acesso ao modelo.');$j=$r->json();abort_unless(($j['status']??'')==='completed',502,'A IA não concluiu a resposta. Encaminhe para a equipe.');$text='';foreach($j['output']??[]as $o)foreach($o['content']??[]as $c)if(($c['type']??'')==='output_text')$text.=$c['text']??'';
  $answer=self::answer($text);return $answer+['usage'=>['input'=>max(0,(int)($j['usage']['input_tokens']??0)),'output'=>max(0,(int)($j['usage']['output_tokens']??0))]];
 }
 public function voice(int $w,string $sdp,array $session):array {
  try{$r=$this->request($w)->attach('sdp',$sdp)->attach('session',json_encode($session))->post($this->base().'/realtime/calls');}catch(\Throwable $e){abort(502,'Não foi possível conectar a voz. Confira a conexão antes de tentar novamente.');}
  abort_unless($r->successful()&&str_starts_with($r->body(),'v=0'),502,'O provedor não confirmou a conexão de voz.');$location=$r->header('Location');preg_match('~/realtime/calls/([a-zA-Z0-9_-]{1,160})$~',$location,$m);abort_unless(isset($m[1]),502,'O provedor não retornou o identificador da sessão de voz.');return ['sdp'=>$r->body(),'call_id'=>$m[1]];
 }
 public function control(int $w,string $call,string $action,array $body=[]):bool {abort_unless(preg_match('/^[a-zA-Z0-9_-]{1,160}$/D',$call)&&in_array($action,['accept','reject','refer'],true),422);$r=$this->request($w)->post($this->base().'/realtime/calls/'.$call.'/'.$action,$body);return $r->successful();}
 public function hangup(int $w,string $call):bool {if(!preg_match('/^[a-zA-Z0-9_-]{1,160}$/D',$call))return false;try{$r=$this->request($w,true)->post($this->base().'/realtime/calls/'.$call.'/hangup');return $r->successful()||$r->status()===404;}catch(\Throwable $e){return false;}}
}
